class Solution:
    def numOfUnplacedFruits(self, fruits: list[int], baskets: list[int]) -> int:
        n = len(baskets)
        tree = [0] * (4 * n)

        def build(node, l, r):
            if l == r:
                tree[node] = baskets[l]
                return
            mid = (l + r) // 2
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            tree[node] = max(tree[node * 2], tree[node * 2 + 1])

        def query_and_update(node, l, r, val):
            if tree[node] < val:
                return False
            if l == r:
                tree[node] = 0
                return True
            mid = (l + r) // 2
            if tree[node * 2] >= val:
                res = query_and_update(node * 2, l, mid, val)
            else:
                res = query_and_update(node * 2 + 1, mid + 1, r, val)
            tree[node] = max(tree[node * 2], tree[node * 2 + 1])
            return res

        build(1, 0, n - 1)
        unplaced = 0
        for f in fruits:
            if not query_and_update(1, 0, n - 1, f):
                unplaced += 1
        return unplaced

