class Solution:
    def numOfUnplacedFruits(self, fruits: list[int], baskets: list[int]) -> int:
        used = [False] * len(baskets)
        unplaced = 0
        for fruit in fruits:
            placed = False
            for j in range(len(baskets)):
                if not used[j] and baskets[j] >= fruit:
                    used[j] = True
                    placed = True
                    break
            if not placed:
                unplaced += 1
        return unplaced
